21	#include "catlass/gemm/tile/tile_mmad.hpp"
22	
23	namespace Catlass::Gemm::Block {
24	
25	/// checker if the dispatch is `MmadAtlasA2Pingpong` or `MmadPingpong`
26	template <class DispatchPolicy>
27	struct MmadPingpongDispatchChecker {
28	    static constexpr bool value = false;
29	};
30	
31	template <bool ENABLE_UNIT_FLAG>
32	struct MmadPingpongDispatchChecker<MmadAtlasA2Pingpong<ENABLE_UNIT_FLAG>> {
33	    static constexpr bool value = true;
34	};
35	
36	template <
37	    class ArchTag, bool ENABLE_UNIT_FLAG, bool USE_HF32_MODE, uint32_t L0C_STAGES, bool ENABLE_L1_RESIDENT,
38	    uint32_t L1A_STAGES, uint32_t L1B_STAGES, uint32_t L0A_STAGES, uint32_t L0B_STAGES>
39	struct MmadPingpongDispatchChecker<MmadPingpong<
40	    ArchTag, ENABLE_UNIT_FLAG, USE_HF32_MODE, L0C_STAGES, ENABLE_L1_RESIDENT, L1A_STAGES, L1B_STAGES, L0A_STAGES,
41	    L0B_STAGES>> {
42	    static constexpr bool value = true;
43	};
44	
45	/// helper to determine the ping-pong stages
46	template <class DispatchPolicy>
47	struct DispatchStagesGetter {
48	    static constexpr uint32_t STAGES = 1; // Fall back
49	};
50	
51	template <bool ENABLE_UNIT_FLAG>
52	struct DispatchStagesGetter<MmadAtlasA2Pingpong<ENABLE_UNIT_FLAG>> {
53	    static constexpr uint32_t STAGES = 2;
54	};
55	
56	template <
57	    class ArchTag, bool ENABLE_UNIT_FLAG, bool USE_HF32_MODE, uint32_t L0C_STAGES, bool ENABLE_L1_RESIDENT,
58	    uint32_t L1A_STAGES, uint32_t L1B_STAGES, uint32_t L0A_STAGES, uint32_t L0B_STAGES>
59	struct DispatchStagesGetter<MmadPingpong<
60	    ArchTag, ENABLE_UNIT_FLAG, USE_HF32_MODE, L0C_STAGES, ENABLE_L1_RESIDENT, L1A_STAGES, L1B_STAGES, L0A_STAGES,
61	    L0B_STAGES>> {
62	    // Strategy: select the lowest stage as the common STAGES
63	    static constexpr uint32_t L1_STAGES = L1A_STAGES > L1B_STAGES ? L1B_STAGES : L1A_STAGES;
64	    static constexpr uint32_t L0_STAGES = L0A_STAGES > L0B_STAGES ? L0B_STAGES : L0A_STAGES;
65	    static constexpr uint32_t STAGES = L1_STAGES > L0_STAGES ? L0_STAGES : L1_STAGES;
66	};
67	
68	template <
69	    class DispatchPolicy_, class L1TileShape_, class L0TileShape_, class AType_, class BType_, class CType_,
70	    class BiasType_, class TileCopy_, class TileMmad_>
71	struct BlockMmad<
72	    DispatchPolicy_, L1TileShape_, L0TileShape_, AType_, BType_, CType_, BiasType_, TileCopy_, TileMmad_,
73	    std::enable_if_t<MmadPingpongDispatchChecker<DispatchPolicy_>::value>> {
74	public:
75	    // Type Aliases
76	    using DispatchPolicy = DispatchPolicy_;
77	    using ArchTag = typename DispatchPolicy::ArchTag;
78	    using L1TileShape = L1TileShape_;
79	    using L0TileShape = L0TileShape_;
80	    using ElementA = typename AType_::Element;
81	    using LayoutA = typename AType_::Layout;
82	    using ElementB = typename BType_::Element;
83	    using LayoutB = typename BType_::Layout;
84	    using ElementC = typename CType_::Element;
85	    using LayoutC = typename CType_::Layout;
86	    using TileMmad = TileMmad_;
87	    using CopyGmToL1A = typename TileCopy_::CopyGmToL1A;
88	    using CopyGmToL1B = typename TileCopy_::CopyGmToL1B;
89	    using CopyL1ToL0A = typename TileCopy_::CopyL1ToL0A;
90	    using CopyL1ToL0B = typename TileCopy_::CopyL1ToL0B;
91	    using CopyL0CToGm = typename TileCopy_::CopyL0CToGm;
92	    using ElementAccumulator =
93	        typename Gemm::helper::ElementAccumulatorSelector<ElementA, ElementB>::ElementAccumulator;
94	    using LayoutAInL1 = typename CopyL1ToL0A::LayoutSrc;
95	    using LayoutBInL1 = typename CopyL1ToL0B::LayoutSrc;
96	    using LayoutAInL0 = typename CopyL1ToL0A::LayoutDst;
97	    using LayoutBInL0 = typename CopyL1ToL0B::LayoutDst;
98	    using LayoutCInL0 = layout::zN;
99	
100	    using L1AAlignHelper = Gemm::helper::L1AlignHelper<ElementA, LayoutA>;
101	    using L1BAlignHelper = Gemm::helper::L1AlignHelper<ElementB, LayoutB>;
102	
103	    static constexpr bool ENABLE_UNIT_FLAG = DispatchPolicy::ENABLE_UNIT_FLAG;
104	    static constexpr uint32_t STAGES = DispatchStagesGetter<DispatchPolicy>::STAGES;
105	    static constexpr uint32_t L1A_SIZE = L1TileShape::M * L1TileShape::K * sizeof(ElementA);
106	    static constexpr uint32_t L1B_SIZE = L1TileShape::N * L1TileShape::K * sizeof(ElementB);
107	    static constexpr uint32_t L0A_SIZE = ArchTag::L0A_SIZE;
108	    static constexpr uint32_t L0B_SIZE = ArchTag::L0B_SIZE;
109	    static constexpr uint32_t L0C_SIZE = ArchTag::L0C_SIZE;
110	    static constexpr uint32_t L0A_PINGPONG_BUF_SIZE = L0A_SIZE / STAGES;
111	    static constexpr uint32_t L0B_PINGPONG_BUF_SIZE = L0B_SIZE / STAGES;
112	
113	    // Check ArchTag
114	    static_assert(
115	        std::is_same_v<ArchTag, Arch::AtlasA2> || std::is_same_v<ArchTag, Arch::Ascend950>,
116	        "ArchTag can only be AtlasA2 or Ascend950!");
117	
118	    // Check LayoutC
119	    static_assert(std::is_same_v<LayoutC, layout::RowMajor>, "LayoutC only support RowMajor yet!");
120	
121	    // Check L1TileShape
122	    static_assert((L1A_SIZE * STAGES + L1B_SIZE * STAGES) <= ArchTag::L1_SIZE, "L1TileShape exceeding the L1 space!");
123	
124	    // Check L0TileShape
125	    static constexpr uint32_t L0A_TILE_SIZE = L0TileShape::M * L0TileShape::K * sizeof(ElementA);
126	    static constexpr uint32_t L0B_TILE_SIZE = L0TileShape::K * L0TileShape::N * sizeof(ElementB);
127	    static constexpr uint32_t L0C_TILE_SIZE = L0TileShape::M * L0TileShape::N * sizeof(ElementAccumulator);
128	    static_assert((L0A_TILE_SIZE * STAGES) <= L0A_SIZE, "L0TileShape exceeding the L0A space!");
129	    static_assert((L0B_TILE_SIZE * STAGES) <= L0B_SIZE, "L0TileShape exceeding the L0B space!");
130	    static_assert(L0C_TILE_SIZE <= L0C_SIZE, "L0TileShape exceeding the L0C space!");
131	
132	    // Check tileshape
133	    static_assert(
134	        L1TileShape::M == L0TileShape::M && L1TileShape::N == L0TileShape::N,
135	        "The situation where the basic blocks of L1 and L0 differ on the m and n axes is not supported yet");
136	    static_assert(L0TileShape::K <= L1TileShape::K, "L0TileShape::K cannot exceed L1TileShape::K");
137	
138	    // 32B (256b) aligned
139	    static_assert(
140	        Gemm::helper::TileShapeAlignChecker<L1TileShape, L0TileShape, ElementA, ElementB>::_ALIGN == 256,
141	        "Tile shape must be 32B aligned.");
142	
143	    /// Construct
144	    CATLASS_DEVICE
145	    BlockMmad(Arch::Resource<ArchTag>& resource, uint32_t l1BufAddrStart = 0)
146	    {
147	        uint32_t l1AOffset = l1BufAddrStart;
148	        uint32_t l1BOffset = l1BufAddrStart + L1A_SIZE * STAGES;
149	        // Init buffers
150	        for (uint32_t i = 0; i < STAGES; i++) {
151	            // Assign L1/L0A/L0B space for each stages
152	            l1ATensorList[i] = resource.l1Buf.template GetBufferByByte<ElementA>(l1AOffset + L1A_SIZE * i);
153	            l1BTensorList[i] = resource.l1Buf.template GetBufferByByte<ElementB>(l1BOffset + L1B_SIZE * i);
154	            l0ATensorList[i] = resource.l0ABuf.template GetBufferByByte<ElementA>(L0A_PINGPONG_BUF_SIZE * i);
155	            l0BTensorList[i] = resource.l0BBuf.template GetBufferByByte<ElementB>(L0B_PINGPONG_BUF_SIZE * i);
156	
157	            // Assign event ID for each stages
158	            l1AEventList[i] = i;
159	            l1BEventList[i] = i + STAGES;
160	            l0AEventList[i] = i;
161	            l0BEventList[i] = i + STAGES;
162	
163	            // The event id that needs to be set before the loop
164	            AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[i]);
165	            AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[i]);
166	            AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[i]);
167	            AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[i]);
168	        }
169	        l0CTensor = resource.l0CBuf.template GetBufferByByte<ElementAccumulator>(0);
170	        AscendC::SetFlag<AscendC::HardEvent::FIX_M>(EVENT_ID0);
171	    }
172	
173	    /// Destructor
174	    CATLASS_DEVICE
175	    ~BlockMmad()
176	    {
177	        for (uint32_t i = 0; i < STAGES; i++) {
178	            AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[i]);
179	            AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[i]);
180	            AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[i]);
181	            AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[i]);
182	        }
183	        AscendC::WaitFlag<AscendC::HardEvent::FIX_M>(EVENT_ID0);
184	    }
185	
186	    /// Perform a block-scoped matrix multiply-accumulate
187	    CATLASS_DEVICE
188	    void operator()(
189	        AscendC::GlobalTensor<ElementA> const& gmA, LayoutA const& layoutA, AscendC::GlobalTensor<ElementB> const& gmB,
190	        LayoutB const& layoutB, AscendC::GlobalTensor<ElementC> const& gmC, LayoutC const& layoutC,
191	        GemmCoord const& actualShape)
192	    {
193	        uint32_t mRound = RoundUp<L1AAlignHelper::M_ALIGNED>(actualShape.m());
194	        uint32_t nRound = RoundUp<L1BAlignHelper::N_ALIGNED>(actualShape.n());
195	
196	        auto layoutAInL1 = LayoutAInL1::template MakeLayout<ElementA>(L1TileShape::M, L1TileShape::K);
197	        auto layoutBInL1 = LayoutBInL1::template MakeLayout<ElementB>(L1TileShape::K, L1TileShape::N);
198	        auto layoutInL0C = LayoutCInL0::MakeLayoutInL0C(MakeCoord(mRound, nRound));
199	
200	        uint32_t kActual = min(actualShape.k(), L1TileShape::K);
201	
202	        // load first matrix A tile from GM to L1
203	        AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[l1ListId]);
204	        auto layoutTileA = layoutA.GetTileLayout(MakeCoord(actualShape.m(), kActual));
205	        copyGmToL1A(l1ATensorList[l1ListId], gmA, layoutAInL1, layoutTileA);
206	        AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[l1ListId]);
207	
208	        // load first matrix B tile from GM to L1
209	        AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[l1ListId]);
210	        auto layoutTileB = layoutB.GetTileLayout(MakeCoord(kActual, actualShape.n()));
211	        copyGmToL1B(l1BTensorList[l1ListId], gmB, layoutBInL1, layoutTileB);
212	        AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[l1ListId]);
213	
214	        if constexpr (!ENABLE_UNIT_FLAG) {
215	            AscendC::WaitFlag<AscendC::HardEvent::FIX_M>(EVENT_ID0);
216	        }
217	
218	        uint32_t mPartLoop = CeilDiv<L0TileShape::M>(mRound);
219	        uint32_t nPartLoop = CeilDiv<L0TileShape::N>(nRound);
220	
221	        // main loop
222	        uint32_t kTileCount = CeilDiv<L1TileShape::K>(actualShape.k());
223	        for (uint32_t kLoopIdx = 0; kLoopIdx < kTileCount; kLoopIdx++) {
224	            uint32_t l1ListIdNext = (l1ListId + 1 < STAGES) ? (l1ListId + 1) : 0;
225	            uint32_t kActualNext{0};
226	            // preload next tile from GM to L1
227	            if (kLoopIdx < kTileCount - 1) {
228	                uint32_t kLoopIdxNext = kLoopIdx + 1;
229	                kActualNext = (kLoopIdxNext < kTileCount - 1) ? L1TileShape::K :
230	                                                                (actualShape.k() - kLoopIdxNext * L1TileShape::K);
231	
232	                // Get L1 tensor for next stage
233	                auto l1ATensor = l1ATensorList[l1ListIdNext];
234	                auto l1BTensor = l1BTensorList[l1ListIdNext];
235	                // Get GM tile for next stage
236	                MatrixCoord gmTileAOffset{0, kLoopIdxNext * L1TileShape::K};
237	                MatrixCoord gmTileBOffset{kLoopIdxNext * L1TileShape::K, 0};
238	                auto gmTileA = gmA[layoutA.GetOffset(gmTileAOffset)];
239	                auto gmTileB = gmB[layoutB.GetOffset(gmTileBOffset)];
240	
241	                // load next matrix A tile from GM to L1
242	                AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[l1ListIdNext]);
243	                layoutTileA = layoutA.GetTileLayout(MakeCoord(actualShape.m(), kActualNext));
244	                copyGmToL1A(l1ATensor, gmTileA, layoutAInL1, layoutTileA);
245	                AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[l1ListIdNext]);
246	
247	                // load next matrix B tile from GM to L1
248	                AscendC::WaitFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[l1ListIdNext]);
249	                layoutTileB = layoutB.GetTileLayout(MakeCoord(kActualNext, actualShape.n()));
250	                copyGmToL1B(l1BTensor, gmTileB, layoutBInL1, layoutTileB);
251	                AscendC::SetFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[l1ListIdNext]);
252	            }
253	
254	            // Get L1 tensor for current stage
255	            auto l1ATensor = l1ATensorList[l1ListId];
256	            auto l1BTensor = l1BTensorList[l1ListId];
257	
258	            // Get the loop nums on L0
259	            uint32_t kPartLoop = CeilDiv<L0TileShape::K>(kActual);
260	
261	            for (int mPartIdx = 0; mPartIdx < mPartLoop; mPartIdx++) {
262	                uint32_t mPartActual =
263	                    (mPartIdx < mPartLoop - 1) ? L0TileShape::M : (mRound - mPartIdx * L0TileShape::M);
264	
265	                for (int kPartIdx = 0; kPartIdx < kPartLoop; kPartIdx++) {
266	                    uint32_t kPartActual =
267	                        (kPartIdx < kPartLoop - 1) ? L0TileShape::K : (kActual - kPartIdx * L0TileShape::K);
268	
269	                    // Locate the current tile on L0A
270	                    auto l0ATile = l0ATensorList[l0AListId];
271	                    LayoutAInL0 layoutAInL0 = LayoutAInL0::template MakeLayout<ElementA>(mPartActual, kPartActual);
272	                    // Locate the current tile of matrix A on L1
273	                    MatrixCoord l1AOffset{mPartIdx * L0TileShape::M, kPartIdx * L0TileShape::K};
274	                    auto l1ATile = l1ATensor[layoutAInL1.GetOffset(l1AOffset)];
275	
276	                    AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[l0AListId]);
277	                    if ((mPartIdx == 0) && (kPartIdx == 0)) {
278	                        AscendC::WaitFlag<AscendC::HardEvent::MTE2_MTE1>(l1AEventList[l1ListId]);
279	                    }
280	
281	                    // Load current tile from L1 to L0A
282	                    copyL1ToL0A(l0ATile, l1ATile, layoutAInL0, layoutAInL1);
283	
284	                    if ((mPartIdx == mPartLoop - 1) && (kPartIdx == kPartLoop - 1)) {
285	                        AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1AEventList[l1ListId]);
286	                    }
287	
288	                    for (int nPartIdx = 0; nPartIdx < nPartLoop; nPartIdx++) {
289	                        uint32_t nPartActual =
290	                            (nPartIdx < nPartLoop - 1) ? L0TileShape::N : (nRound - nPartIdx * L0TileShape::N);
291	
292	                        // Locate the current tile on L0B
293	                        auto l0BTile = l0BTensorList[l0BListId];
294	                        LayoutBInL0 layoutBInL0 = LayoutBInL0::template MakeLayout<ElementB>(kPartActual, nPartActual);
295	                        // Locate the current tile of matrix B on L1
296	                        MatrixCoord l1BOffset{kPartIdx * L0TileShape::K, nPartIdx * L0TileShape::N};
297	                        auto l1BTile = l1BTensor[layoutBInL1.GetOffset(l1BOffset)];
298	
299	                        // Wait for mmad finished
300	                        AscendC::WaitFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[l0BListId]);
301	                        // If the current tile is the first one on the k&n axis, wait for loading matrix B from GM to L1
302	                        if ((kPartIdx == 0) && (nPartIdx == 0)) {
303	                            AscendC::WaitFlag<AscendC::HardEvent::MTE2_MTE1>(l1BEventList[l1ListId]);
304	                        }
305	
306	                        // Load current tile from L1 to L0B
307	                        copyL1ToL0B(l0BTile, l1BTile, layoutBInL0, layoutBInL1);
308	
309	                        // If the current tile is the last one on the k&n axis, notify to load matrix B from GM to L1
310	                        if ((kPartIdx == kPartLoop - 1) && (nPartIdx == nPartLoop - 1)) {
311	                            AscendC::SetFlag<AscendC::HardEvent::MTE1_MTE2>(l1BEventList[l1ListId]);
312	                        }
313	                        // Notify to do mmad
314	                        AscendC::SetFlag<AscendC::HardEvent::MTE1_M>(EVENT_ID0);
315	
316	                        // Locate the current tile on L0C
317	                        MatrixCoord l0COffset{mPartIdx * L0TileShape::M, nPartIdx * L0TileShape::N};
318	                        auto l0CTile = l0CTensor[layoutInL0C.GetOffset(l0COffset)];
319	
320	                        // Compute the matrix multiplication on L0A and L0B and write the result to the accumulator
321	                        // Wait for loading L0B
322	                        AscendC::WaitFlag<AscendC::HardEvent::MTE1_M>(EVENT_ID0);
323	
324	                        // If the current tile is the first tile on the k axis, the accumulator needs to be reset to 0
325	                        bool initC = ((kLoopIdx == 0) && (kPartIdx == 0));
326	                        // If the unit flag is enabled, the unit flag is set according to the calculation progress
327	                        uint8_t unitFlag = 0b00;
328	                        if constexpr (ENABLE_UNIT_FLAG) {
329	                            if ((kLoopIdx == kTileCount - 1) && (mPartIdx == mPartLoop - 1) &&
330	                                (kPartIdx == kPartLoop - 1) && (nPartIdx == nPartLoop - 1)) {
331	                                unitFlag = 0b11;
332	                            } else {
333	                                unitFlag = 0b10;
334	                            }
335	                        }
336	                        // Perform calculation operations
337	                        tileMmad(l0CTile, l0ATile, l0BTile, mPartActual, nPartActual, kPartActual, initC, unitFlag);
338	
339	                        // Notify to move the next L0B tile
340	                        AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0BEventList[l0BListId]);
341	                        l0BListId = (l0BListId + 1 < STAGES) ? (l0BListId + 1) : 0;
342	                    }
343	                    AscendC::SetFlag<AscendC::HardEvent::M_MTE1>(l0AEventList[l0AListId]);
344	                    l0AListId = (l0AListId + 1 < STAGES) ? (l0AListId + 1) : 0;
345	                }
346	            }
347	            l1ListId = l1ListIdNext;
348	            kActual = kActualNext;
349	        }
350	
351	        // copy block out
352	        LayoutC layoutBlock = layoutC.GetTileLayout(actualShape.GetCoordMN());
353	
354	        if constexpr (!ENABLE_UNIT_FLAG) {
355	            AscendC::SetFlag<AscendC::HardEvent::M_FIX>(EVENT_ID0);
356	            AscendC::WaitFlag<AscendC::HardEvent::M_FIX>(EVENT_ID0);
357	            copyL0CToGm(gmC, l0CTensor, layoutBlock, layoutInL0C);
358	            AscendC::SetFlag<AscendC::HardEvent::FIX_M>(EVENT_ID0);
359	        } else {
360	            copyL0CToGm(gmC, l0CTensor, layoutBlock, layoutInL0C, 0b11);
361	        }
362	    }
363	
364	protected:
365	    // Multi-stage tensors list
366	    AscendC::LocalTensor<ElementA> l1ATensorList[STAGES];
367	    AscendC::LocalTensor<ElementB> l1BTensorList[STAGES];
368	    AscendC::LocalTensor<ElementA> l0ATensorList[STAGES];
369	    AscendC::LocalTensor<ElementB> l0BTensorList[STAGES];
370	    AscendC::LocalTensor<ElementAccumulator> l0CTensor;
371	
372	    // Multi-stage event id list
373	    int32_t l1AEventList[STAGES];
374	    int32_t l1BEventList[STAGES];
375	    int32_t l0AEventList[STAGES];
376	    int32_t l0BEventList[STAGES];
377	
378	    // The id of current stage
379	    uint32_t l1ListId{0};
380	    uint32_t l0AListId{0};
381	    uint32_t l0BListId{0};
382	
383	    TileMmad tileMmad;
384	    CopyGmToL1A copyGmToL1A;
385	    CopyGmToL1B copyGmToL1B;
386	    CopyL1ToL0A copyL1ToL0A;
387	    CopyL1ToL0B copyL1ToL0B;
388	    CopyL0CToGm copyL0CToGm;
389	};
390	
391	} // namespace Catlass::Gemm::Block
392	
393	#endif // CATLASS_GEMM_BLOCK_BLOCK_MMAD_PINGPONG_HPP
394

